function validate([root, x, y]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least two nodes.';
  const values = root.filter(v => v !== null);
  if (values.length < 2 || values.length > 100) return 'The tree has 2 to 100 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each node value is a whole number from 1 to 100.';
  if (new Set(values).size !== values.length) return 'Node values must be distinct.';
  // Every non-null entry after the root needs a real parent in level order.
  let slots = 2, next = 1;
  while (next < root.length) {
    if (slots === 0) return 'Every value after the root needs a parent node.';
    let opened = 0;
    for (let s = 0; s < slots && next < root.length; s++) if (root[next++] !== null) opened += 2;
    slots = opened;
  }
  if (x === y) return 'x and y must be different.';
  if (!values.includes(x) || !values.includes(y)) return 'x and y must both be values in the tree.';
  return null;
}

