function generate(rand, size) {
  const pick = limit => Math.floor(rand() * limit);
  const count = size === 'large' ? 100 : 2 + pick(9);
  const pool = Array.from({ length: 100 }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) { const j = pick(i + 1); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  // Attach each new node to a random free child slot; sometimes prefer the newest node for deeper trees.
  const root = { val: pool[0], left: null, right: null, depth: 0 };
  const nodes = [root];
  const free = [[root, 'left'], [root, 'right']];
  const deep = rand() < 0.3;
  for (let k = 1; k < count; k++) {
    const index = deep && rand() < 0.7 ? free.length - 1 - pick(Math.min(2, free.length)) : pick(free.length);
    const [parent, side] = free.splice(index, 1)[0];
    const child = { val: pool[k], left: null, right: null, depth: parent.depth + 1 };
    parent[side] = child;
    nodes.push(child);
    free.push([child, 'left'], [child, 'right']);
  }
  const out = [];
  const queue = [root];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  // Half the time pick two nodes on the same level, so cousins and siblings both appear often.
  const byDepth = {};
  for (const node of nodes) (byDepth[node.depth] ??= []).push(node);
  const levels = Object.values(byDepth).filter(list => list.length >= 2);
  let a, b;
  if (levels.length && rand() < 0.6) {
    const list = levels[pick(levels.length)];
    const i = pick(list.length);
    let j = pick(list.length - 1);
    if (j >= i) j++;
    [a, b] = [list[i], list[j]];
  } else {
    const i = pick(count);
    let j = pick(count - 1);
    if (j >= i) j++;
    [a, b] = [nodes[i], nodes[j]];
  }
  return [out, a.val, b.val];
}
